110	        return Err(RuntimeError::ArityMismatch {
111	            func: name.into(),
112	            expected: 2,
113	            got: args.len(),
114	        });
115	    }
116	    Ok(args[0].apply_binop(&args[1], f64::powf)?)
117	}
