135	    if args.len() != 1 {
136	        return Err(RuntimeError::ArityMismatch {
137	            func: name.into(),
138	            expected: 1,
139	            got: args.len(),
140	        });
141	    }
142	    let data = args[0].data();
143	    let sum: f64 = data.iter().sum();
144	    let count = data.len().max(1) as f64;
