148	/// Pure scalar learning-rate schedule built-ins.
149	///
150	/// - `cosine_schedule(step, total, lr_min, lr_max)`:
151	///   `lr_min + 0.5*(lr_max - lr_min)*(1 + cos(pi * step/total))`,
152	///   clamped to `[lr_min, lr_max]` for `step` outside `[0, total]`.
153	/// - `linear_warmup(step, warmup, lr)`:
154	///   `lr * min(1, step/warmup)`, clamped to `[0, lr]`.
155	fn schedule(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
156	    let expected = if name == "cosine_schedule" { 4 } else { 3 };
157	    if args.len() != expected {
158	        return Err(RuntimeError::ArityMismatch {
159	            func: name.into(),
160	            expected,
161	            got: args.len(),
162	        });
163	    }
164	    for (i, a) in args.iter().enumerate() {
165	        if a.rank() != 0 {
166	            return Err(RuntimeError::InvalidArgument {
167	                func: name.into(),
168	                reason: format!("argument {i} must be a scalar, got rank {}", a.rank()),
169	            });
170	        }
171	    }
172	    let v = if name == "cosine_schedule" {
173	        let step = args[0].data()[0];
174	        let total = args[1].data()[0];
175	        let lr_min = args[2].data()[0];
176	        let lr_max = args[3].data()[0];
177	        if total <= 0.0 {
178	            lr_max
179	        } else {
180	            let t = step.clamp(0.0, total) / total;
181	            lr_min + 0.5 * (lr_max - lr_min) * (1.0 + (std::f64::consts::PI * t).cos())
182	        }
183	    } else {
184	        let step = args[0].data()[0];
185	        let warmup = args[1].data()[0];
186	        let lr = args[2].data()[0];
187	        if warmup <= 0.0 {
188	            lr
189	        } else {
190	            lr * (step / warmup).clamp(0.0, 1.0)
191	        }
192	    };
193	    Ok(DenseArray::from_scalar(v))
194	}
