241	fn constructor(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
242	    if name == "fill" {
243	        if args.len() != 2 {
244	            return Err(RuntimeError::ArityMismatch {
245	                func: name.into(),
246	                expected: 2,
247	                got: args.len(),
248	            });
249	        }
250	        if args[1].rank() != 0 {
251	            return Err(RuntimeError::InvalidArgument {
252	                func: name.into(),
253	                reason: "value must be scalar".into(),
254	            });
255	        }
256	        let dims: Vec<usize> = args[0].data().iter().map(|&d| d as usize).collect();
257	        let count = dims.iter().product();
258	        Ok(DenseArray::new(
259	            Shape::new(dims),
260	            vec![args[1].data()[0]; count],
261	        )?)
262	    } else {
263	        if args.len() != 1 {
264	            return Err(RuntimeError::ArityMismatch {
265	                func: name.into(),
266	                expected: 1,
267	                got: args.len(),
268	            });
269	        }
270	        let dims: Vec<usize> = args[0].data().iter().map(|&d| d as usize).collect();
271	        let val = if name == "zeros" { 0.0 } else { 1.0 };
272	        let count = dims.iter().product();
273	        Ok(DenseArray::new(Shape::new(dims), vec![val; count])?)
