1	//! `Display` impls for AST nodes plus the shared rendering
2	//! helpers (`fmt_scope`, `fmt_comma_seq`, `fmt_record_lit`,
3	//! `write_seq`). Extracted from `ast.rs` so the AST module
4	//! itself only declares types + spans, keeping it under the
5	//! sw-checklist module-fn-count cap.
6	//!
7	//! Used by `device("mlx") { ... }` block forwarding (Saga R1
8	//! step 003) and by user-facing error messages that quote
9	//! source spans back to the caller.
10	
11	use std::fmt;
12	
13	use crate::ast::{BinOpKind, Expr, TensorCtorKind};
14	
15	impl fmt::Display for BinOpKind {
16	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
17	        let s = match self {
18	            Self::Add => "+",
19	            Self::Sub => "-",
20	            Self::Mul => "*",
21	            Self::Div => "/",
22	        };
23	        write!(f, "{s}")
24	    }
25	}
26	
27	impl fmt::Display for TensorCtorKind {
28	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
29	        let s = match self {
30	            Self::Param => "param",
31	            Self::Tensor => "tensor",
32	        };
33	        write!(f, "{s}")
34	    }
35	}
36	
37	fn fmt_comma_seq(f: &mut fmt::Formatter<'_>, exprs: &[Expr]) -> fmt::Result {
38	    for (i, e) in exprs.iter().enumerate() {
39	        if i > 0 {
40	            write!(f, ", ")?;
41	        }
42	        write!(f, "{e}")?;
43	    }
44	    Ok(())
45	}
46	
47	fn fmt_scope(f: &mut fmt::Formatter<'_>, head: &dyn fmt::Display, body: &[Expr]) -> fmt::Result {
48	    write!(f, "{head} {{ ")?;
49	    for (i, e) in body.iter().enumerate() {
50	        if i > 0 {
51	            write!(f, "; ")?;
52	        }
53	        write!(f, "{e}")?;
54	    }
55	    write!(f, " }}")
56	}
57	
58	impl fmt::Display for Expr {
59	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
60	        match self {
61	            Self::IntLit(n, _) => write!(f, "{n}"),
62	            Self::FloatLit(x, _) if x.fract() == 0.0 && x.is_finite() => write!(f, "{x:.1}"),
63	            Self::FloatLit(x, _) => write!(f, "{x}"),
64	            Self::StrLit(s, _) => write!(f, "\"{}\"", s.replace('\\', "\\\\").replace('"', "\\\"")),
65	            Self::Ident(name, _) => write!(f, "{name}"),
