185	    /// Parse `return` or `return expr`.
186	    pub(crate) fn parse_return(&mut self) -> Result<Expr, ParseError> {
187	        let start = self.tokens[self.pos].span;
188	        self.pos += 1;
189	        let value = if crate::parser::can_start_expr(self.tokens.get(self.pos).map(|t| &t.kind)) {
190	            let v = self.parse_expr(0)?;
191	            Some(Box::new(v))
192	        } else {
193	            None
194	        };
195	        let end = value.as_ref().map_or(start, |v| v.span());
196	        Ok(Expr::Return {
197	            value,
198	            span: Span::new(start.start, end.end),
199	        })
200	    }
201	
202	    /// Consume `{ stmt? (sep stmt)* }` and return the parsed body
203	    /// plus the closing brace's span. Shared by `parse_repeat`
204	    /// (which also handles `train`) and `parse_for`.
205	    pub(crate) fn parse_braced_body(&mut self) -> Result<(Vec<Expr>, Span), ParseError> {
206	        let open = self.expect(&TokenKind::LBrace)?;
207	        self.skip_sep();
208	        let mut body = Vec::new();
209	        while self.pos < self.tokens.len()
210	            && !self.is(TokenKind::RBrace)
211	            && self.tokens[self.pos].kind != TokenKind::Eof
212	        {
